-- ========================================================
-- DATABASE SCHEMA: toeic_db (MySQL)
-- Hệ thống luyện thi TOEIC trực tuyến & Ôn luyện từ vựng
-- ========================================================

CREATE DATABASE IF NOT EXISTS `toeic_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `toeic_db`;

-- Xóa bảng cũ theo thứ tự khóa ngoại
DROP TABLE IF EXISTS `user_results`;
DROP TABLE IF EXISTS `questions`;
DROP TABLE IF EXISTS `test_parts`;
DROP TABLE IF EXISTS `tests`;
DROP TABLE IF EXISTS `grammar_questions`;
DROP TABLE IF EXISTS `grammar_topics`;
DROP TABLE IF EXISTS `vocabularies`;
DROP TABLE IF EXISTS `users`;

-- 1. BẢNG NGƯỜI DÙNG (USERS)
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `full_name` VARCHAR(100) NOT NULL,
  `email` VARCHAR(150) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `role` ENUM('User', 'Admin') NOT NULL DEFAULT 'User',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. BẢNG ĐỀ THI (TESTS)
CREATE TABLE `tests` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `level` VARCHAR(50) NOT NULL DEFAULT 'Dễ',
  `duration` INT NOT NULL DEFAULT 30,
  `total_questions` INT NOT NULL DEFAULT 0,
  `description` TEXT,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. BẢNG PHẦN THI TRONG ĐỀ (TEST_PARTS)
CREATE TABLE `test_parts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `test_id` INT NOT NULL,
  `part_number` INT NOT NULL,
  `name` VARCHAR(150) NOT NULL,
  `passage` TEXT NULL,
  FOREIGN KEY (`test_id`) REFERENCES `tests`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. BẢNG CÂU HỎI (QUESTIONS)
CREATE TABLE `questions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `test_part_id` INT NOT NULL,
  `question_text` TEXT NOT NULL,
  `image_url` VARCHAR(500) NULL,
  `audio_url` VARCHAR(500) NULL,
  `option_a` TEXT NOT NULL,
  `option_b` TEXT NOT NULL,
  `option_c` TEXT NOT NULL,
  `option_d` TEXT NOT NULL,
  `correct_answer` ENUM('A', 'B', 'C', 'D') NOT NULL,
  `explanation` TEXT NULL,
  FOREIGN KEY (`test_part_id`) REFERENCES `test_parts`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. BẢNG KẾT QUẢ THI CỦA NGƯỜI DÙNG (USER_RESULTS)
CREATE TABLE `user_results` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `test_id` INT NOT NULL,
  `score` INT NOT NULL,
  `total_questions` INT NOT NULL,
  `completed_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`test_id`) REFERENCES `tests`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. BẢNG TỪ VỰNG VÀ CỤM TỪ (VOCABULARIES)
CREATE TABLE `vocabularies` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `word_or_phrase` VARCHAR(255) NOT NULL,
  `phonetic` VARCHAR(100) NULL,
  `word_type` VARCHAR(50) NOT NULL DEFAULT 'noun',
  `meaning` TEXT NOT NULL,
  `example_sentence` TEXT NULL,
  `example_meaning` TEXT NULL,
  `category` VARCHAR(100) NOT NULL DEFAULT 'Tổng hợp',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 7. BẢNG CHỦ ĐIỂM NGỮ PHÁP (GRAMMAR_TOPICS)
CREATE TABLE `grammar_topics` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(100) NOT NULL UNIQUE,
  `level` VARCHAR(100) NOT NULL DEFAULT 'Trọng tâm Part 5',
  `summary` TEXT NULL,
  `tips` JSON NULL,
  `theory` LONGTEXT NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. BẢNG CÂU HỎI LUYỆN TẬP NGỮ PHÁP (GRAMMAR_QUESTIONS)
CREATE TABLE `grammar_questions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `topic_id` INT NOT NULL,
  `question_text` TEXT NOT NULL,
  `option_a` TEXT NOT NULL,
  `option_b` TEXT NOT NULL,
  `option_c` TEXT NOT NULL,
  `option_d` TEXT NOT NULL,
  `correct_answer` ENUM('A', 'B', 'C', 'D') NOT NULL,
  `explanation` TEXT NULL,
  FOREIGN KEY (`topic_id`) REFERENCES `grammar_topics`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

