(2, 'TOEIC Mini Test 02', 'Trung bình', 45, 4, 'Đề luyện Reading tập trung Part 6 (Text Completion) và Part 7 (Reading Comprehension).'),
(3, 'TOEIC Full Practice 01', 'Khó', 120, 4, 'Đề mô phỏng đầy đủ các Part, dùng để luyện thi thực chiến.');
INSERT INTO `test_parts` (`id`, `test_id`, `part_number`, `name`, `passage`) VALUES
(1, 1, 1, 'Photographs', NULL),
(2, 1, 5, 'Incomplete Sentences', NULL),
(3, 2, 6, 'Text Completion', 'Dear Ms. Brown, Thank you for your interest in our training program. We will send the detailed schedule next week.'),
(4, 2, 7, 'Reading Comprehension', 'The city library will be closed on Monday for maintenance. Normal business hours will resume on Tuesday at 9:00 A.M.');
INSERT INTO `questions` (`test_part_id`, `question_text`, `image_url`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`) VALUES
(1, 'Look at the picture and choose the best description.', 'https://placehold.co/640x360/e0f2fe/0f172a?text=TOEIC+Part+1', 'A man is reading a newspaper.', 'A woman is using a computer.', 'People are sitting in a car.', 'The chairs are being moved.', 'B', 'Trong tranh minh họa, người phụ nữ đang dùng máy tính.'),
(2, 'The manager will review the report ______ the meeting begins.', NULL, 'before', 'between', 'during', 'among', 'A', 'Before + mệnh đề chỉ thời gian: trước khi cuộc họp bắt đầu.'),
(2, 'All employees must submit ______ timesheets by Friday.', NULL, 'they', 'their', 'them', 'theirs', 'B', 'Cần tính từ sở hữu đứng trước danh từ timesheets.');
INSERT INTO `vocabularies` (`word_or_phrase`, `phonetic`, `word_type`, `meaning`, `example_sentence`, `example_meaning`, `category`) VALUES
('comply with', '/kəmˈplaɪ wɪð/', 'phrasal_verb', 'tuân thủ theo, làm theo (quy định, luật lệ)', 'All employees must comply with the company safety regulations.', 'Tất cả nhân viên phải tuân thủ các quy định an toàn của công ty.', 'Cụm từ TOEIC ăn điểm'),
('in accordance with', '/ɪn əˈkɔː.dəns wɪð/', 'collocation', 'phù hợp với, theo đúng như (quy chuẩn, thỏa thuận)', 'The building was renovated in accordance with environmental standards.', 'Tòa nhà đã được cải tạo theo đúng các tiêu chuẩn môi trường.', 'Cụm từ TOEIC ăn điểm'),
('look forward to', '/lʊk ˈfɔː.wəd tuː/', 'phrasal_verb', 'rất mong đợi, trông chờ (+ V-ing / Danh từ)', 'We look forward to receiving your feedback on the proposal.', 'Chúng tôi rất mong nhận được phản hồi của bạn về bản đề xuất.', 'Cụm từ TOEIC ăn điểm'),
('take responsibility for', '/teɪk rɪˌspɒn.sɪˈbɪl.ə.ti fɔːr/', 'collocation', 'chịu trách nhiệm về việc gì', 'The project manager took full responsibility for the project delay.', 'Trưởng dự án đã nhận toàn bộ trách nhiệm về sự chậm trễ của dự án.', 'Cụm từ TOEIC ăn điểm'),
('under warranty', '/ˈʌn.dər ˈwɒr.ən.ti/', 'collocation', 'còn trong thời hạn bảo hành', 'Repairs are completely free because the photocopier is still under warranty.', 'Việc sửa chữa hoàn toàn miễn phí vì máy photocopy vẫn còn trong thời hạn bảo hành.', 'Cụm từ TOEIC ăn điểm'),
('conduct a survey', '/kənˈdʌkt ə ˈsɜː.veɪ/', 'collocation', 'tiến hành một cuộc khảo sát, nghiên cứu', 'The marketing department decided to conduct a survey on consumer habits.', 'Phòng tiếp thị quyết định tiến hành một cuộc khảo sát về thói quen người tiêu dùng.', 'Cụm từ TOEIC ăn điểm'),
('submit an application', '/səbˈmɪt ən ˌæp.lɪˈkeɪ.ʃən/', 'collocation', 'nộp hồ sơ ứng tuyển, nộp đơn', 'Interested applicants must submit an application before the end of the month.', 'Ứng viên quan tâm phải nộp đơn ứng tuyển trước cuối tháng.', 'Cụm từ TOEIC ăn điểm'),
('in charge of', '/ɪn tʃɑːdʒ ɒv/', 'collocation', 'chịu trách nhiệm, phụ trách chính', 'Ms. Lan is in charge of organizing the international trade conference.', 'Cô Lan phụ trách tổ chức hội nghị thương mại quốc tế.', 'Cụm từ TOEIC ăn điểm'),
('reach a consensus', '/riːtʃ ə kənˈsen.səs/', 'collocation', 'đạt được sự đồng thuận, nhất trí', 'After hours of negotiation, both sides finally reached a consensus.', 'Sau nhiều giờ đàm phán, cả hai bên cuối cùng đã đạt được sự đồng thuận.', 'Cụm từ TOEIC ăn điểm'),
('prior to', '/ˈpraɪ.ər tuː/', 'preposition', 'trước khi (tương đương before)', 'All attendees must register online prior to attending the workshop.', 'Tất cả người tham gia phải đăng ký trực tuyến trước khi tham dự hội thảo.', 'Cụm từ TOEIC ăn điểm'),
('take advantage of', '/teɪk ədˈvɑːn.tɪdʒ ɒv/', 'collocation', 'tận dụng, nắm bắt cơ hội tốt', 'You should take advantage of the discount promotion this weekend.', 'Bạn nên tận dụng chương trình ưu đãi giảm giá vào cuối tuần này.', 'Cụm từ TOEIC ăn điểm'),
('adhere to', '/ədˈhɪər tuː/', 'phrasal_verb', 'tuân thủ chặt chẽ, gắn bó với', 'Every laboratory technician must adhere to the chemical safety protocols.', 'Mỗi kỹ thuật viên phòng thí nghiệm đều phải tuân thủ các quy tắc an toàn hóa chất.', 'Cụm từ TOEIC ăn điểm'),
('abide by', '/abide by/', 'verb', 'tuân thủ, làm theo', 'The company expects all staff to understand the concept of abide by thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of abide by thoroughly."', 'Bài 1: Hợp đồng (Contracts)'),
('agreement', '/agreement/', 'noun', 'sự thỏa thuận, hợp đồng', 'The men are signing an agreement.', 'Ví dụ thực tế trong đề thi TOEIC: "The men are signing an agreement."', 'Bài 1: Hợp đồng (Contracts)'),
('assurance', '/assurance/', 'noun', 'sự đảm bảo, sự chắc chắn, sự tự tin', 'The assurance of quality.', 'Ví dụ thực tế trong đề thi TOEIC: "The assurance of quality."', 'Bài 1: Hợp đồng (Contracts)'),
('cancellation', '/cancellation/', 'noun', 'sự hủy bỏ', 'A cancellation clause.', 'Ví dụ thực tế trong đề thi TOEIC: "A cancellation clause."', 'Bài 1: Hợp đồng (Contracts)'),
('determine', '/determine/', 'verb', 'xác định, quyết định', 'The company expects all staff to understand the concept of determine thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of determine thoroughly."', 'Bài 1: Hợp đồng (Contracts)'),
('engage', '/engage/', 'verb', 'tham gia, thu hút', 'The company expects all staff to understand the concept of engage thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of engage thoroughly."', 'Bài 1: Hợp đồng (Contracts)'),
('establish', '/establish/', 'verb', 'thành lập, thiết lập', 'The company expects all staff to understand the concept of establish thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of establish thoroughly."', 'Bài 1: Hợp đồng (Contracts)'),
('obligate', '/obligate/', 'verb', 'bắt buộc, ép buộc', 'The company expects all staff to understand the concept of obligate thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of obligate thoroughly."', 'Bài 1: Hợp đồng (Contracts)'),
('party', '/party/', 'noun', 'bên (trong hợp đồng, vụ kiện), đảng phái, nhóm người', 'The signers are having a party.', 'Ví dụ thực tế trong đề thi TOEIC: "The signers are having a party."', 'Bài 1: Hợp đồng (Contracts)'),
('provision', '/provision/', 'noun', 'điều khoản, sự dự phòng', 'A provision in case of bankruptcy.', 'Ví dụ thực tế trong đề thi TOEIC: "A provision in case of bankruptcy."', 'Bài 1: Hợp đồng (Contracts)'),
('resolve', '/resolve/', 'verb', 'giải quyết, quyết tâm', '[M] Do you think we will ever resolve our difficulties with the computer company? (4-C)', 'Ví dụ thực tế trong đề thi TOEIC: "[M] Do you think we will ever resolve our difficulties with the computer company? (4-C)"', 'Bài 1: Hợp đồng (Contracts)'),
('specific', '/specific/', 'adjective', 'cụ thể, đặc biệt', 'The company expects all staff to understand the concept of specific thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of specific thoroughly."', 'Bài 1: Hợp đồng (Contracts)'),
('attract thu', '/attract thu/', 'verb', 'hút, lôi cuốn', 'The company expects all staff to understand the concept of attract thu thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of attract thu thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('compare so', '/compare so/', 'verb', 'sánh', 'The company expects all staff to understand the concept of compare so thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of compare so thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('competition', '/competition/', 'noun', 'sự cạnh tranh, cuộc thi', 'Who the competition is.', 'Ví dụ thực tế trong đề thi TOEIC: "Who the competition is."', 'Bài 2: Tiếp thị (Marketing)'),
('consume', '/consume/', 'verb', 'tiêu thụ, sử dụng', 'The company expects all staff to understand the concept of consume thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of consume thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('convince', '/convince/', 'verb', 'thuyết phục', 'To attract new customers, we must first convince them that we offer something', 'Ví dụ thực tế trong đề thi TOEIC: "To attract new customers, we must first convince them that we offer something"', 'Bài 2: Tiếp thị (Marketing)'),
('currently', '/currently/', 'verb', 'hiện tại, hiện nay', 'There''s currently a recession.', 'Ví dụ thực tế trong đề thi TOEIC: "There''s currently a recession."', 'Bài 2: Tiếp thị (Marketing)'),
('fad', '/fad/', 'noun', 'mốt nhất thời, trào lưu', 'The company expects all staff to understand the concept of fad thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of fad thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('inspiration', '/inspiration/', 'noun', 'nguồn cảm hứng, sự truyền cảm hứng', 'The company expects all staff to understand the concept of inspiration thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of inspiration thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('market', '/market/', 'verb', 'tiếp thị, bán hàng; thị trường', 'compete in our market. We need to attract more customers to our store and our products.', 'Ví dụ thực tế trong đề thi TOEIC: "compete in our market. We need to attract more customers to our store and our products."', 'Bài 2: Tiếp thị (Marketing)'),
('persuasion', '/persuasion/', 'noun', 'sự thuyết phục, khả năng thuyết phục', 'The company expects all staff to understand the concept of persuasion thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of persuasion thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('productive', '/productive/', 'adjective', 'năng suất, hiệu quả', 'The company expects all staff to understand the concept of productive thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of productive thoroughly."', 'Bài 2: Tiếp thị (Marketing)'),
('satisfaction', '/satisfaction/', 'noun', 'sự hài lòng, sự thỏa mãn', 'Satisfaction is guaranteed.', 'Ví dụ thực tế trong đề thi TOEIC: "Satisfaction is guaranteed."', 'Bài 2: Tiếp thị (Marketing)'),
('characteristic', '/characteristic/', 'noun', 'đặc trưng, tiêu biểu', 'intended for. Consequently, they''re not covered. A common characteristic of this type of', 'Ví dụ thực tế trong đề thi TOEIC: "intended for. Consequently, they''re not covered. A common characteristic of this type of"', 'Bài 3: Bảo hành (Warranties)'),
('consequence', '/consequence/', 'noun', 'hậu quả, kết quả', 'The company expects all staff to understand the concept of consequence thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of consequence thoroughly."', 'Bài 3: Bảo hành (Warranties)'),
('consider', '/consider/', 'verb', 'cân nhắc, xem xét', 'might want to consider purchasing a two-year, sixty-thousand-mile extended warranty.', 'Ví dụ thực tế trong đề thi TOEIC: "might want to consider purchasing a two-year, sixty-thousand-mile extended warranty."', 'Bài 3: Bảo hành (Warranties)'),
('cover bao', '/cover bao/', 'verb', 'gồm, chi trả', 'The company expects all staff to understand the concept of cover bao thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of cover bao thoroughly."', 'Bài 3: Bảo hành (Warranties)'),
('expiration', '/expiration/', 'noun', 'sự hết hạn, thời hạn cuối', 'They''re checking the expiration date.', 'Ví dụ thực tế trong đề thi TOEIC: "They''re checking the expiration date."', 'Bài 3: Bảo hành (Warranties)'),
('frequently', '/frequently/', 'verb', 'thường xuyên, hay xảy ra', 'We frequently receive items that are still under warranty, but we don''t automatically', 'Ví dụ thực tế trong đề thi TOEIC: "We frequently receive items that are still under warranty, but we don''t automatically"', 'Bài 3: Bảo hành (Warranties)'),
('imply', '/imply/', 'verb', 'ngụ ý, ám chỉ', 'The company expects all staff to understand the concept of imply thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of imply thoroughly."', 'Bài 3: Bảo hành (Warranties)'),
('promise', '/promise/', 'verb', 'lời hứa, sự cam kết', 'promise our customers that all our products will operate smoothly every time when', 'Ví dụ thực tế trong đề thi TOEIC: "promise our customers that all our products will operate smoothly every time when"', 'Bài 3: Bảo hành (Warranties)'),
('protect', '/protect/', 'verb', 'bảo vệ, che chở', 'The company expects all staff to understand the concept of protect thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of protect thoroughly."', 'Bài 3: Bảo hành (Warranties)'),
('reputation danh', '/reputation danh/', 'noun', 'tiếng, tiếng tăm', 'The company expects all staff to understand the concept of reputation danh thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of reputation danh thoroughly."', 'Bài 3: Bảo hành (Warranties)'),
('require', '/require/', 'verb', 'yêu cầu, đòi hỏi', '[M] (5-B) The terms of the warranty require you to choose a mechanic from our approved', 'Ví dụ thực tế trong đề thi TOEIC: "[M] (5-B) The terms of the warranty require you to choose a mechanic from our approved"', 'Bài 3: Bảo hành (Warranties)'),
('variety', '/variety/', 'noun', 'sự đa dạng, nhiều loại', 'The company expects all staff to understand the concept of variety thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of variety thoroughly."', 'Bài 3: Bảo hành (Warranties)'),
('address', '/address/', 'verb', 'trình bày, phát biểu; bài phát biểu trang trọng', 'The company expects all staff to understand the concept of address thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of address thoroughly."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('avoid', '/avoid/', 'verb', 'tránh, né tránh', '[W] (4-D) I know she is very serious about careful planning to avoid making obvious', 'Ví dụ thực tế trong đề thi TOEIC: "[W] (4-D) I know she is very serious about careful planning to avoid making obvious"', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('demonstrate', '/demonstrate/', 'verb', 'chứng minh, cho thấy rõ', 'The company expects all staff to understand the concept of demonstrate thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of demonstrate thoroughly."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('develop', '/develop/', 'verb', 'phát triển, mở rộng, cải thiện', 'growth comes from profits. We believe that this is the best way to develop a strong', 'Ví dụ thực tế trong đề thi TOEIC: "growth comes from profits. We believe that this is the best way to develop a strong"', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('evaluate', '/evaluate/', 'verb', 'đánh giá, định giá', 'The company expects all staff to understand the concept of evaluate thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of evaluate thoroughly."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('gather thu', '/gather thu/', 'verb', 'thập, tập hợp', 'The company expects all staff to understand the concept of gather thu thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of gather thu thoroughly."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('offer', '/offer/', 'noun', 'lời đề nghị, sự chào mời; đề nghị, mời', '[M] I’d be happy to offer to help with that. I’m very proud of her. Going into business for', 'Ví dụ thực tế trong đề thi TOEIC: "[M] I’d be happy to offer to help with that. I’m very proud of her. Going into business for"', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('primarily', '/primarily/', 'verb', 'chủ yếu, trước hết', 'The company expects all staff to understand the concept of primarily thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of primarily thoroughly."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('risk', '/risk/', 'noun', 'rủi ro, nguy cơ', 'She has taken on too much risk.', 'Ví dụ thực tế trong đề thi TOEIC: "She has taken on too much risk."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('strategy', '/strategy/', 'noun', 'chiến lược, kế hoạch hành động', 'most important strategy for success?', 'Ví dụ thực tế trong đề thi TOEIC: "most important strategy for success?"', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('strong', '/strong/', 'adjective', 'mạnh mẽ, vững chắc, có sức thuyết phục', 'growth comes from profits. We believe that this is the best way to develop a strong', 'Ví dụ thực tế trong đề thi TOEIC: "growth comes from profits. We believe that this is the best way to develop a strong"', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('substitution', '/substitution/', 'noun', 'sự thay thế, vật thay thế', 'The company expects all staff to understand the concept of substitution thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of substitution thoroughly."', 'Bài 4: Kế hoạch kinh doanh (Business Planning)'),
('accommodate', '/accommodate/', 'verb', 'đáp ứng, cung cấp chỗ ở/nơi làm việc/nhu cầu', '[W] Not yet. (4-C) It’s difficult to find a site that can accommodate a group of our size.', 'Ví dụ thực tế trong đề thi TOEIC: "[W] Not yet. (4-C) It’s difficult to find a site that can accommodate a group of our size."', 'Bài 5: Hội nghị (Conferences)'),
('arrangement', '/arrangement/', 'noun', 'sự sắp xếp, kế hoạch', 'The company expects all staff to understand the concept of arrangement thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of arrangement thoroughly."', 'Bài 5: Hội nghị (Conferences)'),
('association', '/association/', 'noun', 'hiệp hội, tổ chức', 'The company expects all staff to understand the concept of association thoroughly.', 'Ví dụ thực tế trong đề thi TOEIC: "The company expects all staff to understand the concept of association thoroughly."', 'Bài 5: Hội nghị (Conferences)'),
('attend', '/attend/', 'verb', 'tham dự, có mặt', 'How many will attend the conference?', 'Ví dụ thực tế trong đề thi TOEIC: "How many will attend the conference?"', 'Bài 5: Hội nghị (Conferences)'),
('get in touch', '/get in touch/', 'verb', 'liên lạc, giữ liên lạc', 'For example, conference planners are asked to get in touch with us ahead of time if any', 'Ví dụ thực tế trong đề thi TOEIC: "For example, conference planners are asked to get in touch with us ahead of time if any"', 'Bài 5: Hội nghị (Conferences)'),
