INSERT INTO `grammar_topics` (`id`, `title`, `slug`, `level`, `summary`, `tips`, `theory`) VALUES
(1, 'Bài 1: Câu Từ Loại (Word Forms)', 'tu-loai', 'Trọng tâm Part 5 (30-40% đề thi)', 'Cách nhận biết Danh từ, Tính từ, Động từ, Trạng từ qua hậu tố và quy tắc vị trí trong câu Part 5 TOEIC.', '["Không cần dịch hết câu: hãy quan sát từ đứng ngay trước và ngay sau chỗ trống để xác định từ loại cần điền.","Sau Mạo từ (a, an, the), Tính từ sở hữu (my, your, their...), Từ chỉ số lượng (all, many, several) cần Danh từ.","Cụm Danh từ chuẩn: (a/an/the) + ADV + ADJ + NOUN. Ví dụ: a really beautiful girl.","Cảnh giác danh từ có đuôi dễ nhầm với tính từ: đuôi -IVE (representative: người đại diện, initiative: sáng kiến, alternative: phương án thay thế), đuôi -AL (proposal: đề xuất, approval: sự phê duyệt, arrival: sự đến, renewal: sự gia hạn).","Danh từ đếm được số ít không bao giờ đứng trơ trọi một mình (phải có a/an/the hoặc số nhiều -s/-es)."]', '\n### 1. Dấu hiệu nhận biết các loại từ qua hậu tố (Suffixes)\n* **Danh từ (Noun):** Thường kết thúc bằng: `-tion, -ment, -ness, -ence, -ance, -ty, -cy, -ure, -ism, -er, -or, -ast`.\n  * *Ví dụ:* *development, happiness, confidence, quality, privacy, importance, procedure, supervisor.*\n* **Tính từ (Adjective):** Thường kết thúc bằng: `-able, -ible, -ful, -ic, -al, -ent, -ant, -ive, -ous, -ed, -ing`.\n  * *Ví dụ:* *reliable, successful, economic, commercial, independent, competitive, dangerous, excited, exciting.*\n* **Trạng từ (Adverb):** Cấu tạo bằng: **ADV = ADJ + ly**.\n  * *Ví dụ:* *quickly, precisely, regularly, significantly, completely.*\n* **Động từ (Verb):** Thường kết thúc bằng: `-ize, -ise, -ate, -fy, -en`.\n  * *Ví dụ:* *organize, evaluate, simplify, strengthen.*\n\n---\n\n### 2. Các công thức vị trí vàng của Danh từ và Tính từ\n* **Adj + N:** *a beautiful park*\n* **Adj + Adj + N:** *a big modern building*\n* **Adv + Adj + N:** *a really productive morning*\n* **N + N (Danh từ ghép):** *a food market, application form, construction site*\n* **To be + Adj:** *The procedure is simple.*\n* **Linking verbs + Adj:** *become, seem, look, sound, feel, remain, keep + ADJ*\n  * *Ví dụ:* *remain competitive, keep the room clean, become successful.*\n* **Cấu trúc Make / Find / Consider:** `Make / Find / Keep / Deem / Consider + O + ADJ`\n  * *Ví dụ:* *We find this software very useful.*\n\n---\n\n### 3. Cụm danh từ TOEIC kinh điển Part 5\n* **Application form:** Mẫu đơn xin việc\n* **Customer satisfaction:** Sự hài lòng của khách hàng\n* **Expiration date:** Ngày hết hạn\n* **Fringe benefits:** Phúc lợi bổ sung, chế độ thưởng\n* **Performance appraisal:** Đánh giá năng lực công việc\n* **Dress-code regulation:** Quy định về trang phục\n* **Construction site:** Công trường xây dựng\n    '),
(2, 'Bài 2: Mệnh Đề Quan Hệ (Relative Clauses)', 'menh-de-quan-he', 'Trọng tâm Part 5 (Thường gặp 2-3 câu)', 'Phân biệt Who, Whom, Whose, Which, That và kỹ năng giải nhanh rút gọn mệnh đề quan hệ (V-ing vs V-ed).', '["WHO + Động từ (V): đại diện cho người làm chủ ngữ.","WHOM + Mệnh đề (S + V): đại diện cho người làm tân ngữ.","WHOSE + Danh từ (N): chỉ sự sở hữu (whose car, whose parents).","THAT KHÔNG đi sau dấu phẩy (,) và KHÔNG đi sau Giới từ (in, at, with...).","THAT bắt buộc hoặc ưu tiên dùng sau: all, every, any, the only, the very, và cấp so sánh nhất.","Mẹo rút gọn mệnh đề quan hệ: Chủ động -> dùng V-ing (có tân ngữ phía sau); Bị động -> dùng V-ed/PII (không có tân ngữ theo sau)."]', '\n### 1. Bảng đại từ quan hệ trong tiếng Anh\n| Đại từ | Thay cho | Vị trí trong mệnh đề | Ví dụ |\n| :--- | :--- | :--- | :--- |\n| **WHO** | Người | Chủ ngữ (+ V) | *The employee **who works** in Marketing* |\n| **WHOM** | Người | Tân ngữ (+ S + V) | *The candidate **whom we interviewed** yesterday* |\n| **WHOSE** | Người / Vật | Sở hữu (+ N) | *The author **whose book** is a bestseller* |\n| **WHICH** | Vật / Động vật | Chủ ngữ / Tân ngữ | *The report **which was submitted** yesterday* |\n| **THAT** | Người / Vật | Chủ ngữ / Tân ngữ | *The only computer **that works** properly* |\n\n---\n\n### 2. Quy tắc bắt buộc với "THAT"\n* Dùng sau các đại từ bất định và từ hạn định: *all, every, any, each, the only, the very*.\n* Dùng sau **tính từ so sánh nhất**: *the most beautiful girl that I have ever met*.\n* **CẤM:** Tuyệt đối không dùng *THAT* ngay sau giới từ (*in, on, with that* -> SAI) hoặc sau dấu phẩy trong mệnh đề không xác định.\n\n---\n\n### 3. Rút gọn mệnh đề quan hệ (Rất hay ra trong Part 5 & 6)\n* **Dạng Chủ Động -> Dùng V-ing (+ O):**\n  * Gốc: *The employee who works in Marketing arrives late.*\n  * Rút gọn: *The employee **working** in Marketing arrives late.*\n* **Dạng Bị Động -> Dùng V-ed / PII (Không có O):**\n  * Gốc: *The employee who was hired last week performs well.*\n  * Rút gọn: *The employee **hired** last week performs well.*\n    '),
(3, 'Bài 3: Tính Từ (V-ed vs V-ing & Tính từ gốc)', 'tinh-tu', 'Trọng tâm Part 5 (Xuất hiện 20-25% câu ngữ pháp)', 'Quy tắc phân biệt Tính từ chỉ bản chất (V-ing) và Cảm xúc (V-ed), mẹo chọn tính từ gốc và các Linking Verbs thường gặp.', '["V-ing: miêu tả bản chất của sự vật, hiện tượng hoặc chủ thể chủ động tạo ra cảm giác (an exciting game, surprising news).","V-ed: miêu tả cảm xúc, tâm trạng của con người khi tiếp nhận tác động (I am excited, pleased, satisfied).","MẸO THI 100%: Khi đáp án có Tính từ gốc (-ive, -ic, -al...) và V-ing -> Chọn tính từ gốc!","MẸO THI 74%: Khi đáp án có Tính từ gốc và V-ed -> 74% Tính từ gốc đúng, 26% V-ed đúng.","Cấu trúc giả định: It is essential / imperative / crucial / necessary + that + S + (should) + V-bare / be PII."]', '\n### 1. Phân biệt V-ed và V-ing làm tính từ\n* **V-ing (Chủ động / Bản chất):**\n  * *The movie is boring.* (Bộ phim có bản chất nhàm chán)\n  * *A demanding client* (Vị khách hàng khó tính)\n  * *An exciting opportunity* (Một cơ hội đầy hào hứng)\n* **V-ed (Bị động / Cảm xúc con người):**\n  * *The audience felt bored.* (Khán giả cảm thấy buồn ngủ)\n  * *We are pleased to announce...* (Chúng tôi rất vui mừng được thông báo)\n  * *Satisfied customers* (Những khách hàng cảm thấy hài lòng)\n\n---\n\n### 2. Các Động từ nối (Linking Verbs) luôn đi với Tính Từ\n```\nS + (seem / look / sound / taste / smell / feel / stay / keep / remain / become / be) + ADJECTIVE\n```\n* *Ví dụ:*\n  * *The room looks spacious.*\n  * *Please remain calm.*\n  * *Prices remain competitive.*\n\n---\n\n### 3. Cụm Tính từ + Giới từ hay ra nhất trong TOEIC\n* **Be available for / to:** Sẵn sàng cho\n* **Be eligible for:** Đủ tư cách, đủ điều kiện hưởng\n* **Be responsible for:** Chịu trách nhiệm về\n* **Be familiar with:** Quen thuộc với\n* **Be comparable to / with:** Có thể so sánh được với\n* **Be satisfied with:** Hài lòng với\n* **Be consistent with:** Nhất quán, phù hợp với\n* **Be superior to:** Vượt trội hơn so với\n    '),
(4, 'Bài 4: Động Từ (To-V, V-ing, Gerunds & Infinitives)', 'dong-tu', 'Trọng tâm Part 5 (Thường gặp 3-4 câu)', 'Cấu trúc To-V chỉ mục đích, V-ing làm chủ ngữ/tân ngữ, và quy tắc giới từ luôn đi với V-ing.', '["To-V / In order to / So as to + V-bare: dùng để chỉ mục đích hành động.","V-ing làm chủ ngữ thì động từ chính của câu LUÔN chia ở số ít (Developing new methods is crucial).","Giới từ (in, on, at, for, about, without, after, before...) + V-ing + Tân ngữ.","Sau To be rất hiếm khi đi thẳng với danh từ đếm được đứng một mình, phần lớn là Tính từ hoặc Phân từ."]', '\n### 1. V-ing đóng vai trò Chủ ngữ hoặc Tân ngữ\n* **Làm chủ ngữ:** V-ing đứng đầu câu làm chủ ngữ của cả câu -> Động từ theo sau luôn chia số ít.\n  * *Developing new software **requires** strong analytical skills.*\n* **Đứng sau giới từ:**\n  * `Giới từ + V-ing + O`\n  * *Thank you for **attending** our annual seminar.*\n  * *She succeeded by **implementing** innovative marketing ideas.*\n\n---\n\n### 2. Các cụm từ To + V-ing đặc biệt hay lừa trong TOEIC\n* **Look forward to + V-ing:** Rất trông mong\n* **Be committed to + V-ing:** Cam kết làm gì\n* **Be dedicated / devoted to + V-ing:** Tận tụy cống hiến\n* **In addition to + V-ing:** Bên cạnh việc\n* **Be used to / get used to + V-ing:** Quen với việc làm gì\n    '),
(5, 'Bài 5: So Sánh Hơn & So Sánh Nhất (Comparisons)', 'so-sanh', 'Trọng tâm Part 5 (Thường gặp 1-2 câu)', 'Công thức so sánh hơn (er/more... than) và so sánh nhất (the -est / the most) với tính từ và trạng từ.', '["Thấy xuất hiện từ THAN trong câu -> 100% chọn cấu trúc so sánh hơn (Adj-er hoặc More + Adj/Adv).","Thấy xuất hiện mạo từ THE trước chỗ trống -> Ưu tiên dạng so sánh nhất (Adj-est hoặc Most + Adj/Adv).","Các từ nhấn mạnh so sánh hơn hay gặp: MUCH, FAR, EVEN, STILL, SIGNIFICANTLY, SUBSTANTIALLY + So sánh hơn."]', '\n### 1. Bảng công thức So Sánh trong TOEIC\n* **So sánh bằng:** `as + Adj / Adv + as`\n  * *The new engine is **as efficient as** the previous model.*\n* **So sánh hơn (Tính từ ngắn):** `Adj + er + than`\n  * *Replacing the network would be **cheaper than** repairing it.*\n* **So sánh hơn (Tính từ / Trạng từ dài):** `more + Adj / Adv + than`\n  * *She solved the problem **more quickly than** her colleagues.*\n* **So sánh nhất:** `the + Adj-est / the most + Adj/Adv`\n  * *He is **the most experienced** engineer on the team.*\n    '),
(6, 'Bài 6: Trạng Từ & Vị Trí Trọng Tâm (Adverbs in Part 5)', 'trang-tu', 'Trọng tâm Part 5 (Thường gặp 4-5 câu)', 'Nắm vững 13 vị trí vàng của trạng từ trong đề thi TOEIC để giải nhanh câu hỏi dưới 10 giây.', '["Trợ động từ (have/has/will/can) + ADV + Động từ chính (100% đúng).","To be + ADV + Tính từ / Phân từ Ved (100% đúng).","ADV + Tính từ + Danh từ (rất hay gặp, tỉ lệ đúng > 93%).","Đã có đầy đủ S + V + O thì vị trí cuối câu hoặc ngay sau V là TRẠNG TỪ."]', '\n### 13 Vị trí quan trọng nhất của Trạng Từ trong đề thi TOEIC\n1. **To be / Linking verb + ADV + Adj / PII:** *The system was **strictly** confidential.*\n2. **Trợ động từ + ADV + Động từ chính:** *The committee will **promptly** review the documents.*\n3. **Chủ ngữ + ADV + Động từ:** *We **sincerely** apologize for the delay.*\n4. **Động từ + O + ADV:** *She fixed the problem **quickly**.*\n5. **Bị động + ADV:** *The vehicle was checked **carefully**.*\n6. **ADV + Tính từ + Danh từ:** *A **consistently** high level of performance.*\n7. **ADV + V-ing:** *Thanks for **promptly** replying to my request.*\n8. **To + ADV + V-bare:** *To **fully** understand the requirements.*\n9. **ADV + Cụm số lượng:** *approximately 500 attendees.*\n10. **Ngoại lệ:** `Make / Keep / Find + O + ADJ` (không dùng adv sau tân ngữ trong mẫu câu này).\n    '),
(7, 'Bài 7: Câu Điều Kiện & Đảo Ngữ (Conditionals & Inversions)', 'cau-dieu-kien', 'Nâng cao Part 5 (Thường là câu phân loại điểm 700+)', 'Công thức câu điều kiện loại 1, 2, 3 và kỹ xảo nhận diện cấu trúc đảo ngữ Should / Were / Had.', '["Unless = If not (Trừ khi, nếu không). Mệnh đề đi liền sau Unless KHÔNG dùng thể phủ định.","Đảo ngữ loại 1: Should + S + V-bare, S + will + V (Should anyone wish to access... = If anyone wishes).","Đảo ngữ loại 2: Were + S + to V / Were I you, S + would + V.","Đảo ngữ loại 3: Had + S + PII, S + would have PII."]', '\n### 1. Bảng 3 loại câu điều kiện căn bản\n* **Loại 1 (Có thật ở hiện tại/tương lai):**\n  * `If + S + V(s/es), S + will / can / may + V-bare`\n  * *If you register early, you will receive a 10% discount.*\n* **Loại 2 (Trái với thực tế ở hiện tại):**\n  * `If + S + V2/ed (to be dùng WERE cho mọi ngôi), S + would / could + V-bare`\n  * *If I were you, I would accept the job offer.*\n* **Loại 3 (Trái với thực tế trong quá khứ):**\n  * `If + S + had + PII, S + would / could + have + PII`\n  * *If they had checked the contract, they would have avoided the penalty.*\n\n---\n\n### 2. Cấu trúc Đảo Ngữ cực kỳ phổ biến trong TOEIC\n* **Đảo ngữ loại 1 (Hay ra nhất):**\n  * `Should + S + (not) + V-bare, S + will / please + V`\n  * *Ví dụ:* ***Should you have** any questions, please contact our support desk.* (= If you have...)\n* **Đảo ngữ loại 2:**\n  * `Were + S + to V / Were + S + Adj/Noun, S + would + V`\n* **Đảo ngữ loại 3:**\n  * `Had + S + (not) + PII, S + would have + PII`\n  * *Ví dụ:* ***Had they taken** our advice, they would have won the contract.*\n    '),
(8, 'Bài 8: Câu Bị Động & Rút Gọn (Passive Voice)', 'bi-dong', 'Trọng tâm Part 5 (Thường gặp 3-4 câu)', 'Công thức bị động các thì, dấu hiệu nhận biết khi không có tân ngữ, và nội động từ không bao giờ chia bị động.', '["Quy tắc vàng: Nếu sau động từ KHÔNG có tân ngữ (Noun) -> Nghĩ ngay đến thể BỊ ĐỘNG (Be + PII).","NỘI ĐỘNG TỪ không bao giờ chia bị động: appear, arrive, become, happen, occur, remain, stay, exist, expire.","Các cụm bị động đi với giới từ: be interested in, be satisfied with, be dedicated to, be exposed to, be equipped with."]', '\n### 1. Công thức bị động qua các thì\n* **Hiện tại đơn:** `am / is / are + PII`\n* **Quá khứ đơn:** `was / were + PII`\n* **Hiện tại tiếp diễn:** `am / is / are + being + PII`\n* **Hiện tại hoàn thành:** `has / have + been + PII`\n* **Động từ khuyết thiếu (Modal verbs):** `will / can / must / should + be + PII`\n\n---\n\n### 2. Danh sách Nội động từ KHÔNG BAO GIỜ chia bị động\n`Appear, Arrive, Become, Come, Disappear, Happen, Occur, Remain, Stay, Exist, Expire`\n* *Ví dụ sai:* The accident was happened. ❌\n* *Ví dụ đúng:* The accident **happened**. ✔️\n\n---\n\n### 3. Cụm từ Bị động TOEIC đi kèm giới từ\n* **Be disappointed / surprised / shocked at:** Thất vọng / ngạc nhiên trước\n* **Be engaged / interested / involved in:** Tham gia / quan tâm / gắn bó vào\n* **Be composed / made of:** Được cấu tạo từ\n* **Be crowded / pleased / satisfied with:** Đông đúc / hài lòng với\n* **Be dedicated / committed / devoted to + V-ing/N:** Cống hiến / cam kết với\n    '),
(9, 'Bài 9: Đại Từ (Pronouns: S, O, Tính từ sở hữu, Phản thân)', 'dai-tu', 'Trọng tâm Part 5 (100% đề thi có 2-3 câu)', 'Nắm vững bảng đại từ chủ ngữ, tân ngữ, tính từ sở hữu, đại từ sở hữu và đại từ phản thân (by oneself / on one\'s own).', '["Trước Danh từ -> Chọn TÍNH TỪ SỞ HỮU (my, your, his, her, their, our). Ví dụ: their equipment, her proposal.","Sau Giới từ \'BY\' hoặc cụm \'ON ... OWN\' -> Chọn ĐẠI TỪ PHẢN THÂN: by himself = on his own (tự thân một mình).","Đại từ phản thân đứng ngay sau Chủ ngữ hoặc cuối câu hoàn chỉnh mang ý nghĩa nhấn mạnh (The CEO himself attended the meeting)."]', '\n### Bảng phân loại Đại từ TOEIC đầy đủ\n| Ngôi | Chủ ngữ (S) | Tân ngữ (O) | Tính từ sở hữu (+N) | Đại từ sở hữu (Đứng 1 mình) | Đại từ phản thân |\n| :--- | :--- | :--- | :--- | :--- | :--- |\n| **Tôi** | I | me | my + N | mine | myself |\n| **Bạn / Các bạn** | you | you | your + N | yours | yourself / yourselves |\n| **Anh ấy** | he | him | his + N | his | himself |\n| **Cô ấy** | she | her | her + N | hers | herself |\n| **Nó** | it | it | its + N | its | itself |\n| **Chúng tôi** | we | us | our + N | ours | ourselves |\n| **Họ** | they | them | their + N | theirs | themselves |\n\n* **Cấu trúc tự mình làm gì:**\n  * `By + Đại từ phản thân` = `On + Tính từ sở hữu + own`\n  * *Ví dụ:* *by herself = on her own* (cô ấy tự mình làm).\n    '),
(10, 'Bài 10: Liên Từ & Giới Từ (Conjunctions & Prepositions)', 'lien-tu-gioi-tu', 'Trọng tâm Part 5 & 6 (Chiếm 30% câu ngữ nghĩa & cấu trúc)', 'Phân biệt liên từ nối mệnh đề (S + V) và giới từ nối cụm danh từ (Noun/V-ing), các cặp liên từ tương hỗ Both/Either/Neither.', '["Phía sau là MỆNH ĐỀ (có Chủ ngữ + Vị ngữ S + V) -> Chọn LIÊN TỪ (Because, Although, While, Once, Since...).","Phía sau là CỤM DANH TỪ hoặc V-ing -> Chọn GIỚI TỪ (Because of, Due to, Despite, In spite of, As a result of...).","Cặp từ đi liền: Both...and, Either...or, Neither...nor, Not only...but also, Whether...or.","Giới từ chỉ thời gian: Within + khoảng thời gian (within 7 days), By + mốc thời gian (by 5 P.M)."]', '\n### 1. Bảng đối chiếu Liên từ vs Giới từ kinh điển TOEIC\n| Ý nghĩa | Liên từ (+ Mệnh đề S + V) | Giới từ (+ Cụm Danh từ / V-ing) |\n| :--- | :--- | :--- |\n| **Bởi vì** | *Because, Since, As, Now that* | *Because of, Due to, Owing to, As a result of* |\n| **Mặc dù** | *Although, Even though, Though* | *Despite, In spite of* |\n| **Trong khi** | *While, Whereas* | *During (+ danh từ thời gian), Throughout* |\n| **Để mà** | *So that, In order that (+ S+V)* | *In order to, So as to (+ V-bare)* |\n\n---\n\n### 2. Các cặp liên từ tương hỗ (Correlative Conjunctions)\n* **Both A and B:** Cả A và B\n* **Either A or B:** Hoặc A hoặc B\n* **Neither A nor B:** Không A cũng không B\n* **Not only A but also B:** Không những A mà còn B\n* **Whether A or B:** Liệu A hay B\n\n---\n\n### 3. Giới từ thời gian đặc biệt hay bẫy\n* **By + mốc thời gian:** Trước hoặc đúng thời điểm đó (*by Friday at 5 P.M.*)\n* **Until + mốc thời gian:** Cho tới tận khi (*open until 9 P.M.*)\n* **Within + khoảng thời gian:** Trong vòng bao lâu (*within 30 days of purchase*)\n    ');
INSERT INTO `grammar_questions` (`id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`) VALUES
(1, 1, 'Our ongoing -------- development seminars allow staff members to develop their skills in various directions.', 'Profession', 'Professionally', 'Professional', 'Professionalism', 'C', 'Trước cụm danh từ development seminars cần một Tính từ (Professional) để bổ nghĩa: professional development seminars (các buổi hội thảo phát triển chuyên môn).'),
(2, 1, 'Crawford Devices is guaranteed to -------- regulate the temperature of any commercial refrigerator.', 'Precisely', 'Precise', 'Precision', 'Preciseness', 'A', 'Giữa to và động từ nguyên mẫu regulate cần một Trạng từ (Precisely) để bổ nghĩa cho động từ: precisely regulate (điều chỉnh một cách chính xác).'),
(3, 1, 'Please remember to review the -------- form before submitting your application for the sales position.', 'Attach', 'Attached', 'Attaching', 'Attachment', 'B', 'Trước danh từ form cần phân từ/tính từ bị động attached mang nghĩa: mẫu đơn được đính kèm.'),
(4, 1, 'The hard work put in during his younger years made him become financially -------- in his later years.', 'Secure', 'Securely', 'Security', 'Securing', 'A', 'Sau linking verb become + trạng từ financially cần một Tính từ secure: an toàn, vững chắc về tài chính.'),
(5, 1, 'To complete the transfer process, all the students should send documents -------- from their previous school\'s administrative office.', 'Directed', 'Director', 'Direct', 'Directly', 'D', 'Cần trạng từ Directly để bổ nghĩa cho động từ send documents (gửi trực tiếp từ văn phòng trường cũ).'),
(6, 1, 'Employees must reserve a time to copy by writing their names on the -------- on the lid of the photocopiers.', 'Schedule', 'Scheduled', 'Schedules', 'Schedulers', 'A', 'Sau mạo từ the cần một danh từ số ít chỉ bảng lịch trình schedule.'),
(7, 1, 'Workshop participants were required to be -------- not to choose any reserved front-row seats.', 'Caution', 'Cautious', 'Cautiously', 'Cautiousness', 'B', 'Sau động từ to be cần tính từ: be cautious (hãy cẩn trọng/lưu ý).'),
(8, 1, 'Road and street signs must be -------- visible even in the distance in order for drivers to know where they are heading.', 'Clearness', 'Clear', 'Clearly', 'Clearest', 'C', 'Trước tính từ visible cần trạng từ clearly để bổ nghĩa: clearly visible (nhìn thấy rõ ràng).'),
(9, 1, 'This course provides students with the tools for thinking about ways to enhance -------- among races, ethnic groups and social classes.', 'Collaborative', 'Collaborate', 'Collaborated', 'Collaboration', 'D', 'Sau ngoại động từ enhance (nâng cao, thúc đẩy) cần một Danh từ làm tân ngữ: collaboration (sự cộng tác, hợp tác).'),
(10, 1, 'The bids must be reviewed by the engineers to make sure all engineering -------- for the project are met.', 'Specific', 'To specify', 'Specifically', 'Specifications', 'D', 'Sau all engineering và đứng trước vị ngữ số nhiều are met cần danh từ số nhiều specifications (các tiêu chuẩn/thông số kỹ thuật).'),
(11, 1, 'The new management recognized the importance of this business decision and -------- reorganized operational procedures.', 'Prompt', 'Promptness', 'Promptly', 'Prompter', 'C', 'Đứng trước động từ quá khứ reorganized cần một Trạng từ promptly (ngay lập tức tái tổ chức quy trình vận hành).'),
(12, 1, 'The -------- has always been on ensuring a consistently high level of quality and outstanding customer service.', 'Emphasized', 'Emphatic', 'Emphasis', 'Emphasize', 'C', 'Sau mạo từ The và đứng làm chủ ngữ của has always been cần một Danh từ emphasis (sự chú trọng/nhấn mạnh).'),
(13, 1, 'It is common practice for a firm to seek a -------- advantage in order to maintain its position in the marketplace.', 'Compete', 'Competition', 'Competitive', 'Competitively', 'C', 'Trước danh từ advantage cần một Tính từ competitive: competitive advantage (lợi thế cạnh tranh).'),
(14, 1, 'One -------- outcome of the current economic recession is that the growth of merger activity will slow down.', 'Possibly', 'Possibility', 'Possibilities', 'Possible', 'D', 'Trước danh từ outcome cần Tính từ possible: One possible outcome (Một kết quả khả dĩ).'),
(15, 1, 'Note that the hotel\'s pool and pool deck will be closed until -------- on them is completed later this month.', 'Construction', 'Constructed', 'Constructs', 'Constructive', 'A', 'Sau liên từ until và đứng làm chủ ngữ của is completed cần Danh từ construction (việc xây dựng/sửa chữa).'),
(16, 2, 'It is the only phone in the office -------- works reliably during power outages.', 'That', 'Which', 'Who', 'Whom', 'A', 'Đứng sau the only + N bắt buộc ưu tiên dùng đại từ quan hệ That.'),
(17, 2, 'She is talking about the author -------- book is one of the best-sellers this year.', 'Which', 'Whose', 'That', 'Who', 'B', 'Chỉ sự sở hữu giữa tác giả và cuốn sách (author\'s book) -> whose book.'),
(18, 2, '-------- who cannot attend the weekly staff meeting must inform their managers immediately.', 'Those', 'That', 'These', 'This', 'A', 'Cấu trúc kinh điển TOEIC: Those who + V (Những ai / Những người mà...).'),
(19, 2, 'The man with -------- I have been working on the project is extremely cooperative.', 'Who', 'That', 'Which', 'Whom', 'D', 'Sau giới từ with chỉ người làm tân ngữ bắt buộc dùng Whom.'),
(20, 2, 'Workers -------- dangerous chemicals are required to wear protective gear such as safety goggles and gloves.', 'Handled', 'Are handling', 'Handling', 'Handle', 'C', 'Rút gọn mệnh đề quan hệ dạng chủ động (Workers who handle...) -> dùng V-ing handling.'),
(21, 2, 'To order by mail, fill out the form in your catalog and mail it in the envelope --------.', 'Provide', 'Provided', 'Provides', 'Providing', 'B', 'Rút gọn mệnh đề quan hệ bị động (the envelope which is provided...) -> dùng PII provided.'),
(22, 2, 'Amin and Sonya, both of -------- sculptures are currently on display in the gallery, are Russell Art students.', 'Who', 'Their', 'They', 'Whose', 'D', 'Đứng sau cả cụm both of và trước danh từ sculptures để chỉ sự sở hữu -> both of whose sculptures.'),
(23, 2, 'The old building -------- is situated in front of our main office was renovated last year.', 'Of which', 'Which', 'Whose', 'Whom', 'B', 'Đại từ quan hệ thay thế cho danh từ chỉ vật the old building làm chủ ngữ -> Which.'),
(24, 2, 'Do you know the young engineer -------- we met at the product presentation last week?', 'Which', 'Whose', 'Who', 'Whom', 'D', 'Đại từ quan hệ thay thế cho người làm tân ngữ (we met him) -> Whom.'),
(25, 2, 'Customers who purchase more than 500 dollars worth of electronics can receive free delivery at no -------- charge.', 'Additional', 'Addition', 'Adding', 'Additionally', 'A', 'Trước danh từ charge cần tính từ additional: at no additional charge (không tính thêm phí).'),
(26, 2, 'All accountants are required to compile a quarterly report which -------- corporate travel expenses in detail.', 'Corresponds', 'Expects', 'Details', 'Prepares', 'C', 'Động từ details mang nghĩa liệt kê chi tiết (details corporate travel expenses).'),
(27, 2, 'The job fair held in the City Exhibition Center was considered the most -------- one so far.', 'Overall', 'Successful', 'Wealthy', 'Delighted', 'B', 'Sau the most cần tính từ mang nghĩa thành công: the most successful one.'),
(28, 3, 'Ms. Jespersen is -------- to accept your invitation to become a member of the advisory committee.', 'Pleasure', 'Please', 'Pleasing', 'Pleased', 'D', 'Chủ ngữ là người \'Ms. Jespersen\', diễn tả cảm xúc vui lòng/hân hạnh -> dùng tính từ V-ed: \'be pleased to do something\'.'),
(29, 3, 'Did you hear the -------- news? Anna is going to be appointed as the new managing director!', 'Surprise', 'Surprised', 'Surprising', 'To surprise', 'C', 'Bổ nghĩa cho danh từ \'news\' (tin tức mang bản chất gây bất ngờ) -> dùng tính từ V-ing: \'surprising news\'.'),
(30, 3, 'The enclosed booklet contains information regarding services that are -------- through Harpers Cleaning Service.', 'Avail', 'Available', 'Availability', 'Avails', 'B', 'Sau động từ to be \'are\' cần một Tính từ bổ nghĩa: \'available\' (có sẵn, khả dụng).'),
(31, 3, 'Pioneer Steel guarantees that all information gathered through this website is strictly --------.', 'Confide', 'Confides', 'Confidential', 'Confidentially', 'C', 'Sau to be \'is\' và trạng từ \'strictly\' cần một Tính từ: \'strictly confidential\' (tuyệt đối bảo mật).'),
(32, 3, 'Job candidates often complain that they found the long waiting time for interview results extremely --------.', 'Exhaustion', 'Exhausting', 'Exhausted', 'Exhaustingly', 'B', 'Cấu trúc: Find + O + Adj. Tân ngữ ở đây là \'the long waiting time\' (thời gian chờ đợi là vật, mang tính chất gây mệt mỏi) -> dùng tính từ V-ing: \'exhausting\'.'),
(33, 3, 'It is imperative that the final contracts -------- at least a month prior to the project launch.', 'Finalize', 'Finalized', 'Be finalized', 'Finalizing', 'C', 'Cấu trúc giả định: It is imperative that + S + (should) + be PII. Hợp đồng phải \'được hoàn tất\' (bị động) nên dùng \'be finalized\'.'),
(34, 4, 'Travel expenses should be -------- no later than 30 calendar days after returning from a business trip.', 'Submit', 'Submits', 'Submitted', 'Submissions', 'C', 'Sau \'should be\' là thể bị động cần quá khứ phân từ PII: \'should be submitted\' (nên được nộp).'),
(35, 4, 'Many residents of Alston have expressed -------- to the construction of a new warehouse complex.', 'Oppose', 'Opposing', 'Opposes', 'Opposition', 'D', 'Sau ngoại động từ \'expressed\' cần một danh từ làm tân ngữ: \'expressed opposition to\' (bày tỏ sự phản đối).'),
(36, 4, 'By -------- the relocation in advance, management was able to minimize unexpected office expenses.', 'Carefully', 'Careful', 'Planning', 'Plan', 'C', 'Sau giới từ \'By\' cần một danh động từ V-ing làm chủ hành động (+ tân ngữ \'the relocation\'): \'By planning...\'.'),
(37, 5, 'The technicians concluded that replacing the network system would be -------- than repairing it.', 'Most cheaply', 'Cheapest', 'More cheaply', 'Cheaper', 'D', 'Sau linking verb \'would be\' cần tính từ, và phía sau có \'than\' nên dùng so sánh hơn của tính từ ngắn: \'cheaper than\'.'),
(38, 5, 'Sunny Valley Enclave has received several proposals from local contractors and will choose the -------- bid.', 'Most affordable', 'More affordable', 'Affordably', 'Affordability', 'A', 'Có mạo từ \'the\' đứng trước chỗ trống và danh từ \'bid\' -> cấu trúc so sánh nhất: \'the most affordable bid\' (mức giá phải chăng nhất).'),
(39, 5, 'Patel Flooring\'s yearly revenue was substantially -------- than that of last year.', 'High', 'Higher', 'Highly', 'Highest', 'B', 'Có từ \'than\' phía sau và trạng từ nhấn mạnh \'substantially\' -> chọn so sánh hơn \'higher\'.'),
(40, 6, 'We -------- apologize for any inconvenience caused by the scheduled power outage.', 'Sincerely', 'Sincere', 'Sincerity', 'More sincere', 'A', 'Vị trí giữa Chủ ngữ \'We\' và Động từ chính \'apologize\' là Trạng từ \'Sincerely\' (chân thành xin lỗi).'),
(41, 6, 'Dr. James Hanser is -------- regarded as the leading renewable energy scientist in the region.', 'Wider', 'Widely', 'Widened', 'Widening', 'B', 'Đứng giữa \'is\' và PII \'regarded\' là Trạng từ \'widely\': \'is widely regarded as\' (được công nhận rộng rãi là).'),
(42, 6, 'Sign up to receive our weekly newsletter and you will -------- receive promotion updates via e-mail.', 'Automatically', 'Automaticity', 'Automated', 'Automatic', 'A', 'Đứng giữa trợ động từ \'will\' và động từ chính \'receive\' là Trạng từ \'Automatically\' (tự động nhận tin).'),
(43, 6, 'Giessen is centrally located in Germany and can -------- be reached by high-speed train or car.', 'Easy', 'Easily', 'Ease', 'Easiness', 'B', 'Đứng giữa khiếm khuyết \'can\' và động từ bị động \'be reached\' cần Trạng từ \'easily\'.'),
(44, 7, '-------- anyone wish to access the status of his or her order, the secure password must be entered.', 'If', 'Should', 'Whether', 'As though', 'B', 'Chủ ngữ là \'anyone\' (số ít) nhưng động từ lại là \'wish\' (nguyên mẫu V-bare) -> Đây là cấu trúc đảo ngữ câu điều kiện loại 1: \'Should + S + V-bare\' (bằng với If anyone wishes).'),
(45, 7, '-------- you require further information regarding hotel accommodations, please contact Ms. Adams.', 'Should', 'Unless', 'Were', 'Provided', 'A', 'Đảo ngữ loại 1: \'Should you require\' = \'If you require\' (Nếu quý khách cần thêm thông tin).'),
(46, 8, 'All the storage rooms are scheduled to undergo renovations and -------- closed for several days next week.', 'Will be', 'Was', 'Are', 'Has been', 'A', 'Có mốc thời gian tương lai \'next week\' -> dùng \'will be\' closed (sẽ bị đóng cửa tạm thời).'),
(47, 8, 'The payment for the purchased machinery must -------- within 4 business days.', 'Receive', 'Received', 'Be received', 'Receiving', 'C', 'Chủ ngữ là \'The payment\' (khoản thanh toán phải được nhận) -> bị động với modal verb: \'must be received\'.'),
(48, 8, 'Questions concerning the billing procedure will be -------- by client support representatives.', 'Handled', 'Replied', 'Attended', 'Exempted', 'A', 'Cụm \'handled by...\' nghĩa là \'được xử lý/giải quyết bởi các đại diện hỗ trợ khách hàng\'.'),
(49, 9, 'Staff who need to replace -------- damaged office equipment must submit an upgrade request form.', 'Them', 'Their', 'Themselves', 'Theirs', 'B', 'Trước cụm danh từ \'damaged office equipment\' cần Tính từ sở hữu \'their\' để bổ nghĩa.'),
(50, 9, 'At this year\'s orientation session, the general manager -------- took the time to welcome all new recruits.', 'She', 'Her', 'Hers', 'Herself', 'D', 'Đứng sau chủ ngữ \'the general manager\' để nhấn mạnh chính bà ấy đã đích thân đón tiếp -> dùng đại từ phản thân \'herself\'.'),
(51, 9, 'Mr. Kurt appears to be the only person on our team who can finish the complex survey by --------.', 'He', 'Him', 'His', 'Himself', 'D', 'Cụm \'by himself\' mang nghĩa \'tự bản thân anh ấy làm một mình mà không cần ai trợ giúp\'.'),
(52, 9, 'Since Mr. Warren has finished writing his sales report, he offered to help Ms. Carol complete --------.', 'Hers', 'Herself', 'Her', 'She', 'A', 'Đại từ sở hữu \'hers\' = \'her sales report\' (báo cáo bán hàng của cô ấy), tránh lặp lại danh từ đã xuất hiện phía trước.'),
(53, 10, '-------- relying on printed evaluations, the branch manager decided to discuss the performance reviews by phone.', 'Acceding to', 'Further', 'Instead of', 'However', 'C', 'Sau chỗ trống là V-ing \'relying on...\' mang nghĩa đối lập \'Thay vì dựa vào các bản đánh giá in ấn...\' -> chọn giới từ \'Instead of\'.'),
(54, 10, '-------- reserve tickets for the annual banquet, please fill in the online reservation form.', 'Furthermore', 'In order to', 'As a result of', 'As to', 'B', 'Đứng trước động từ nguyên mẫu \'reserve\' chỉ mục đích: \'In order to + V-bare\' (Để đặt vé...).'),
(55, 10, '-------- increases in airfares and hotel prices, most salespersons will exceed their travel allowance.', 'In fact', 'Because of', 'Since', 'When', 'B', 'Sau chỗ trống là cụm danh từ \'increases in airfares and hotel prices\' (không có động từ chia thì) -> dùng giới từ chỉ nguyên nhân \'Because of\'.'),
(56, 10, 'Our customers can choose -------- standard shipping or, if their order qualifies, express delivery.', 'And', 'Both', 'Either', 'As', 'C', 'Phía sau có từ \'or\' -> cặp liên từ tương hỗ \'Either ... or ...\' (chọn hoặc vận chuyển tiêu chuẩn hoặc hỏa tốc).'),
(57, 10, 'In order to be registered for our 5-year warranty, please return the registration card -------- 7 days of purchase.', 'During', 'Within', 'Until', 'Before', 'B', 'Trước một khoảng thời gian số lượng \'7 days\' mang nghĩa \'trong vòng 7 ngày\' -> chọn \'Within\'.'),
(58, 10, '-------- the position has been filled, all the other applicants will be notified via email.', 'Despite', 'Once', 'Whereas', 'During', 'B', 'Sau chỗ trống là một mệnh đề hoàn chỉnh S+V \'the position has been filled\'. \'Once\' là liên từ mang nghĩa \'Một khi / Ngay sau khi vị trí đã được tuyển\'.');
